#!/usr/bin/env python3

from __future__ import annotations

import base64
import hashlib
import json
import os
import re
import shlex
import shutil
import stat
import subprocess
import sys
import time
import urllib.error
import urllib.request
import uuid
import zlib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

try:
    import tomllib
except ImportError:  # pragma: no cover
    tomllib = None


VERSION = "2.37.1"

PUBLIC_EXPORT_SHELLS = [
    "bash",
    "elvish",
    "zsh",
    "murex",
    "tcsh",
    "vim",
    "pwsh",
    "fish",
    "gha",
    "gzenv",
    "json",
    "systemd",
]

PRIVATE_COMMANDS = [
    "*apply_dump FILE:",
    "  Accepts a filename containing `direnv dump` output and generates a series of bash export statements to apply the given env",
    "*show_dump DUMP:",
    "  Show the data inside of a dump for debugging purposes",
    "*check-required SHELL ENVRC_PATH PATH...:",
    "  Checks if required files have been allowed",
    "*dotenv [SHELL] [PATH_TO_DOTENV]:",
    "  Transforms a .env file to evaluatable `export KEY=PAIR` statements",
    "*dump [SHELL] [FILE]:",
    "  Used to export the inner bash state at the end of execution",
    "*watch SHELL PATH...:",
    "  Adds a path to the list that direnv watches for changes",
    "*watch-dir SHELL DIR:",
    "  Recursively adds a directory to the list that direnv watches for changes",
    "*watch-list [SHELL]:",
    "  Pipe pairs of `mtime path` to stdin to build a list of files to watch.",
    "*watch-print [--null]:",
    "  prints the watched paths",
    "*current PATH:",
    "  Reports whether direnv's view of a file is current (or stale)",
]

MANAGED_VARS = {
    "DIRENV_DIFF",
    "DIRENV_DIR",
    "DIRENV_FILE",
    "DIRENV_REQUIRED",
    "DIRENV_WATCHES",
}
VOLATILE_VARS = {"OLDPWD", "PWD", "SHLVL", "_"}
EVAL_IGNORED_VARS = MANAGED_VARS | VOLATILE_VARS | {"DIRENV_IN_ENVRC"}


class CLIError(Exception):
    def __init__(self, message: str, exit_code: int = 1) -> None:
        super().__init__(message)
        self.message = message
        self.exit_code = exit_code


@dataclass
class Config:
    bash_path: str
    disable_stdin: bool = False
    load_dotenv: bool = False
    strict_env: bool = False
    warn_timeout: str = "5s"
    hide_env_diff: bool = False
    log_format: str | None = None
    log_filter: str | None = None
    whitelist_prefix: list[str] = field(default_factory=list)
    whitelist_exact: set[str] = field(default_factory=set)


def self_path() -> Path:
    return Path(sys.argv[0]).resolve()


def home_dir() -> Path:
    return Path(os.environ.get("HOME") or str(Path.home())).expanduser()


def xdg_dir(env_name: str, fallback_suffix: str) -> Path:
    value = os.environ.get(env_name)
    if value:
        return Path(value).expanduser()
    return home_dir() / fallback_suffix


def config_dir() -> Path:
    return xdg_dir("XDG_CONFIG_HOME", ".config") / "direnv"


def data_dir() -> Path:
    return xdg_dir("XDG_DATA_HOME", ".local/share") / "direnv"


def cache_dir() -> Path:
    return xdg_dir("XDG_CACHE_HOME", ".cache") / "direnv"


def allow_dir() -> Path:
    return data_dir() / "allow"


def deny_dir() -> Path:
    return data_dir() / "deny"


def allowed_required_dir() -> Path:
    return data_dir() / "allowed-required"


def status_log(message: str) -> None:
    sys.stderr.write(f"\x1b[0mdirenv: {message}\n")


def error_log(message: str) -> None:
    sys.stderr.write(f"\x1b[31mdirenv: error {message}\x1b[0m\n")


def plain_error_log(message: str) -> None:
    sys.stderr.write(f"\x1b[31mdirenv: {message}\x1b[0m\n")


def load_config() -> Config:
    cfg_path = config_dir() / "direnv.toml"
    raw: dict[str, Any] = {}
    if cfg_path.exists() and tomllib is not None:
        with cfg_path.open("rb") as handle:
            raw = tomllib.load(handle)

    global_cfg = raw.get("global", {})
    whitelist_cfg = raw.get("whitelist", {})
    bash_path = global_cfg.get("bash_path") or shutil.which("bash") or "/bin/bash"

    exact_entries: set[str] = set()
    for item in whitelist_cfg.get("exact", []) or []:
        expanded = str(Path(item).expanduser())
        if not expanded.endswith(".envrc") and not expanded.endswith(".env"):
            expanded = str(Path(expanded) / ".envrc")
        exact_entries.add(str(Path(expanded).resolve(strict=False)))

    prefix_entries = [
        str(Path(item).expanduser().resolve(strict=False))
        for item in (whitelist_cfg.get("prefix", []) or [])
    ]

    return Config(
        bash_path=bash_path,
        disable_stdin=bool(global_cfg.get("disable_stdin", False)),
        load_dotenv=bool(global_cfg.get("load_dotenv", False)),
        strict_env=bool(global_cfg.get("strict_env", False)),
        warn_timeout=str(global_cfg.get("warn_timeout", "5s")),
        hide_env_diff=bool(global_cfg.get("hide_env_diff", False)),
        log_format=global_cfg.get("log_format"),
        log_filter=global_cfg.get("log_filter"),
        whitelist_prefix=prefix_entries,
        whitelist_exact=exact_entries,
    )


def read_template() -> str:
    candidates = [
        self_path().with_name("stdlib_template.sh"),
        Path(__file__).resolve().with_name("stdlib_template.sh"),
        Path("/workspace/src/stdlib_template.sh"),
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate.read_text(encoding="utf-8")
    raise CLIError("stdlib_template.sh not found")


def render_stdlib() -> str:
    rendered = read_template()
    escaped = str(self_path()).replace("\\", "\\\\").replace('"', '\\"')
    return rendered.replace("__DIRENV_EXECUTABLE__", escaped)


def path_for_arg(arg: str | None) -> Path | None:
    if arg is None:
        return None
    path = Path(arg).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    return path.resolve(strict=False)


def pick_rc_in_dir(directory: Path, cfg: Config) -> Path | None:
    envrc = directory / ".envrc"
    if envrc.exists():
        return envrc.resolve()
    if cfg.load_dotenv:
        dotenv_path = directory / ".env"
        if dotenv_path.exists():
            return dotenv_path.resolve()
    return None


def discover_rc(start: Path, cfg: Config) -> Path | None:
    current = start.resolve()
    while True:
        found = pick_rc_in_dir(current, cfg)
        if found:
            return found
        if current == current.parent:
            return None
        current = current.parent


def resolve_for_allow_or_block(arg: str | None, cfg: Config) -> Path:
    if arg is None:
        found = discover_rc(Path.cwd(), cfg)
        if found:
            return found
        raise CLIError(".envrc file not found")

    target = path_for_arg(arg)
    assert target is not None
    if target.exists() and target.is_dir():
        found = pick_rc_in_dir(target, cfg)
        if found:
            return found
        raise CLIError(".envrc file not found")

    if target.exists():
        return target

    raise CLIError(".envrc file not found")


def resolve_for_edit(arg: str | None, cfg: Config) -> Path:
    if arg is None:
        found = discover_rc(Path.cwd(), cfg)
        if found:
            return found
        raise CLIError(
            ".envrc or .env not found. Use `direnv edit .` to create a new .envrc in the current directory"
        )

    target = path_for_arg(arg)
    assert target is not None
    if target.exists() and target.is_dir():
        found = pick_rc_in_dir(target, cfg)
        if found:
            return found
        return (target / ".envrc").resolve(strict=False)

    if target.suffix in {".env", ".envrc"} or target.exists():
        return target

    if not target.suffix:
        return (target / ".envrc").resolve(strict=False)
    return target


def resolve_for_reload(cfg: Config) -> Path:
    env_file = os.environ.get("DIRENV_FILE")
    if env_file:
        return Path(env_file).expanduser().resolve(strict=False)
    found = discover_rc(Path.cwd(), cfg)
    if found:
        return found
    raise CLIError(".envrc not found")


def normalize_version(value: str) -> list[int]:
    value = value.strip()
    if value.startswith("v"):
        value = value[1:]
    if not value:
        return [0]
    parts = []
    for part in value.split("."):
        try:
            parts.append(int(part))
        except ValueError:
            parts.append(0)
    return parts


def version_at_least(current: str, required: str) -> bool:
    a = normalize_version(current)
    b = normalize_version(required)
    length = max(len(a), len(b))
    a += [0] * (length - len(a))
    b += [0] * (length - len(b))
    return a >= b


def sha256_hexdigest(*parts: bytes) -> str:
    digest = hashlib.sha256()
    for part in parts:
        digest.update(part)
    return digest.hexdigest()


def rc_bytes(rc_path: Path) -> bytes:
    return rc_path.read_bytes()


def deny_hash(rc_path: Path) -> str:
    return sha256_hexdigest((str(rc_path.resolve()) + "\n").encode("utf-8"))


def allow_hash(rc_path: Path) -> str:
    return sha256_hexdigest(
        (str(rc_path.resolve()) + "\n").encode("utf-8"),
        rc_bytes(rc_path),
    )


def required_bucket(envrc_path: Path) -> Path:
    return allowed_required_dir() / deny_hash(envrc_path)


def required_hash(required_path: Path) -> str:
    return sha256_hexdigest(
        (str(required_path.resolve()) + "\n").encode("utf-8"),
        required_path.read_bytes(),
    )


def whitelisted(rc_path: Path, cfg: Config) -> bool:
    rc = str(rc_path.resolve())
    if rc in cfg.whitelist_exact:
        return True
    return any(rc.startswith(prefix) for prefix in cfg.whitelist_prefix)


def rc_auth_state(rc_path: Path, cfg: Config) -> tuple[int, Path, Path]:
    allow_path = allow_dir() / allow_hash(rc_path)
    deny_path = deny_dir() / deny_hash(rc_path)
    if whitelisted(rc_path, cfg):
        return 0, allow_path, deny_path
    if allow_path.exists():
        return 0, allow_path, deny_path
    if deny_path.exists():
        return 2, allow_path, deny_path
    return 1, allow_path, deny_path


def ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def remove_allow_entries_for_path(rc_path: Path) -> None:
    if not allow_dir().exists():
        return
    target = str(rc_path.resolve())
    for entry in allow_dir().iterdir():
        if not entry.is_file():
            continue
        try:
            contents = entry.read_text(encoding="utf-8").strip()
        except OSError:
            continue
        if contents == target:
            entry.unlink(missing_ok=True)


def allow_rc(rc_path: Path) -> None:
    allow_path = allow_dir() / allow_hash(rc_path)
    deny_path = deny_dir() / deny_hash(rc_path)
    ensure_parent(allow_path)
    allow_path.write_text(f"{rc_path.resolve()}\n", encoding="utf-8")
    deny_path.unlink(missing_ok=True)


def deny_rc(rc_path: Path) -> None:
    deny_path = deny_dir() / deny_hash(rc_path)
    ensure_parent(deny_path)
    deny_path.write_text(f"{rc_path.resolve()}\n", encoding="utf-8")
    remove_allow_entries_for_path(rc_path)


def parse_required_value(value: str | None) -> list[str]:
    if not value:
        return []
    return [line for line in value.splitlines() if line]


def allow_required_files() -> None:
    envrc = os.environ.get("DIRENV_FILE")
    required = parse_required_value(os.environ.get("DIRENV_REQUIRED"))
    if not envrc or not required:
        return
    envrc_path = Path(envrc).expanduser().resolve(strict=False)
    bucket = required_bucket(envrc_path)
    bucket.mkdir(parents=True, exist_ok=True)
    for rel in required:
        status_log(f"allowing {rel}")
        required_path = (envrc_path.parent / rel).resolve()
        if not required_path.exists():
            continue
        entry = bucket / required_hash(required_path)
        entry.write_text(f"{rel}\n", encoding="utf-8")


def prune_entries() -> None:
    if allow_dir().exists():
        for entry in list(allow_dir().iterdir()):
            if not entry.is_file():
                continue
            try:
                rc_path = Path(entry.read_text(encoding="utf-8").strip()).resolve(strict=False)
            except OSError:
                entry.unlink(missing_ok=True)
                continue
            if not rc_path.exists() or entry.name != allow_hash(rc_path):
                entry.unlink(missing_ok=True)
    if deny_dir().exists():
        for entry in list(deny_dir().iterdir()):
            if not entry.is_file():
                continue
            try:
                rc_path = Path(entry.read_text(encoding="utf-8").strip()).resolve(strict=False)
            except OSError:
                entry.unlink(missing_ok=True)
                continue
            if not rc_path.exists() or entry.name != deny_hash(rc_path):
                entry.unlink(missing_ok=True)


def encode_payload(payload: Any) -> str:
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return base64.urlsafe_b64encode(zlib.compress(raw)).decode("ascii").rstrip("=")


def decode_payload(raw: str | None) -> Any:
    if not raw:
        return None
    padding = "=" * ((4 - len(raw) % 4) % 4)
    data = base64.urlsafe_b64decode((raw + padding).encode("ascii"))
    return json.loads(zlib.decompress(data).decode("utf-8"))


def file_signature(path: Path) -> str:
    if not path.exists():
        return "0"
    st = path.stat()
    return f"{int(st.st_mtime_ns)}:{int(st.st_size)}"


def dir_signature(path: Path) -> str:
    if not path.exists():
        return "0"
    digest = hashlib.sha256()
    digest.update(str(path.resolve()).encode("utf-8"))
    for root, dirs, files in os.walk(path):
        dirs.sort()
        files.sort()
        for name in files:
            child = Path(root) / name
            st = child.stat()
            rel = child.relative_to(path)
            digest.update(str(rel).encode("utf-8"))
            digest.update(str(int(st.st_mtime_ns)).encode("ascii"))
            digest.update(str(int(st.st_size)).encode("ascii"))
    return digest.hexdigest()


def make_watch_entry(path: Path, recursive: bool = False) -> dict[str, Any]:
    resolved = path.resolve(strict=False)
    kind = "dir" if recursive or resolved.is_dir() else "file"
    signature = dir_signature(resolved) if kind == "dir" else file_signature(resolved)
    return {
        "kind": kind,
        "path": str(resolved),
        "recursive": recursive,
        "signature": signature,
    }


def decode_watches(raw: str | None) -> list[dict[str, Any]]:
    payload = decode_payload(raw)
    if not isinstance(payload, list):
        return []
    out = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        if "path" not in item:
            continue
        out.append(item)
    return out


def encode_watches(items: list[dict[str, Any]]) -> str:
    ordered = sorted(items, key=lambda item: (item["path"], item.get("recursive", False)))
    return encode_payload(ordered)


def merge_watches(items: list[dict[str, Any]], *extra: dict[str, Any]) -> list[dict[str, Any]]:
    merged: dict[tuple[str, bool], dict[str, Any]] = {}
    for item in items + list(extra):
        merged[(item["path"], bool(item.get("recursive", False)))] = item
    return list(merged.values())


def watches_current(items: list[dict[str, Any]]) -> bool:
    for item in items:
        path = Path(item["path"])
        expected = item.get("signature", "")
        kind = item.get("kind", "file")
        current = dir_signature(path) if kind == "dir" else file_signature(path)
        if expected != current:
            return False
    return True


def reverse_diff_from_env() -> dict[str, str | None]:
    payload = decode_payload(os.environ.get("DIRENV_DIFF"))
    if not isinstance(payload, dict):
        return {}
    out: dict[str, str | None] = {}
    for key, value in payload.items():
        if isinstance(value, str) or value is None:
            out[key] = value
    return out


def apply_reverse_diff(current_env: dict[str, str], reverse_diff: dict[str, str | None]) -> dict[str, str]:
    base = dict(current_env)
    for key, value in reverse_diff.items():
        if value is None:
            base.pop(key, None)
        else:
            base[key] = value
    for key in MANAGED_VARS:
        base.pop(key, None)
    return base


def build_reverse_diff(base_env: dict[str, str], target_env: dict[str, str]) -> dict[str, str | None]:
    diff: dict[str, str | None] = {}
    keys = set(base_env) | set(target_env)
    for key in keys:
        if key in MANAGED_VARS or key in VOLATILE_VARS:
            continue
        base_value = base_env.get(key)
        target_value = target_env.get(key)
        if base_value == target_value:
            continue
        diff[key] = base_value
    return diff


def reverse_ops_from_diff(reverse_diff: dict[str, str | None]) -> dict[str, str | None]:
    return dict(reverse_diff)


def env_delta(from_env: dict[str, str], to_env: dict[str, str], ignored: set[str] | None = None) -> dict[str, str | None]:
    ignored = ignored or set()
    ops: dict[str, str | None] = {}
    keys = set(from_env) | set(to_env)
    for key in keys:
        if key in ignored:
            continue
        before = from_env.get(key)
        after = to_env.get(key)
        if before == after:
            continue
        ops[key] = after
    return ops


def display_path(path: str) -> str:
    try:
        return os.path.relpath(path, str(Path.cwd()))
    except ValueError:
        return path


def mtime_for_display(path: Path) -> str:
    if not path.exists():
        return "1970-01-01T00:00:00Z"
    ts = int(path.stat().st_mtime)
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))


def bash_quote(value: str) -> str:
    out: list[str] = []
    for ch in value:
        code = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == "'":
            out.append("\\'")
        elif ch == "\a":
            out.append("\\a")
        elif ch == "\b":
            out.append("\\b")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\v":
            out.append("\\v")
        elif ch == "\f":
            out.append("\\f")
        elif ch == "\r":
            out.append("\\r")
        elif 32 <= code < 127:
            out.append(ch)
        elif code <= 0xFF:
            out.append(f"\\x{code:02x}")
        else:
            out.append(f"\\u{code:04x}")
    return "$'" + "".join(out) + "'"


def fish_quote(value: str) -> str:
    return "'" + value.replace("\\", "\\\\").replace("'", "\\'") + "'"


def pwsh_quote(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def vim_quote(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def format_export_ops(shell: str, ops: dict[str, str | None]) -> str:
    keys = sorted(ops)
    if shell in {"bash", "zsh"}:
        parts = []
        for key in keys:
            value = ops[key]
            if value is None:
                parts.append(f"unset {key};")
            else:
                parts.append(f"export {key}={bash_quote(value)};")
        return "".join(parts)

    if shell == "fish":
        parts = []
        for key in keys:
            value = ops[key]
            if value is None:
                parts.append(f"set -e -g {fish_quote(key)};")
            elif key == "PATH":
                path_parts = " ".join(fish_quote(part) for part in value.split(":"))
                parts.append(f"set -x -g PATH {path_parts};")
            else:
                parts.append(f"set -x -g {fish_quote(key)} {fish_quote(value)};")
        return "".join(parts)

    if shell in {"json"}:
        payload = {key: ops[key] for key in keys}
        return json.dumps(payload, indent=2, sort_keys=True) + "\n"

    if shell in {"murex", "elvish"}:
        payload = {key: ops[key] for key in keys}
        return json.dumps(payload, separators=(",", ":"), sort_keys=True)

    if shell == "pwsh":
        parts = []
        for key in keys:
            value = ops[key]
            if value is None:
                parts.append(f"Remove-Item -LiteralPath 'env:/{key}';")
            else:
                parts.append(f"${{env:{key}}}={pwsh_quote(value)};")
        return "".join(parts)

    if shell == "vim":
        parts = []
        for key in keys:
            value = ops[key]
            if value is None:
                parts.append(f"call setenv({vim_quote(key)},v:null)\n")
            else:
                parts.append(f"call setenv({vim_quote(key)},{vim_quote(value)})\n")
        return "".join(parts)

    if shell == "tcsh":
        parts = []
        for key in keys:
            value = ops[key]
            if value is None:
                parts.append(f"unsetenv {key} ;")
            elif key == "PATH":
                path_items = " ".join(value.split(":"))
                parts.append(f"set path = ( {path_items} );")
            else:
                escaped = value.replace(" ", "\\ ")
                parts.append(f"setenv {key} {escaped} ;")
        return "".join(parts)

    if shell == "gha":
        blocks = []
        for key in keys:
            value = ops[key]
            if value is None:
                continue
            delimiter = f"ghadelimiter_{uuid.uuid4().hex}"
            blocks.append(f"{key}<<{delimiter}\n{value}\n{delimiter}\n")
        return "".join(blocks)

    if shell == "gzenv":
        return encode_payload({key: ops[key] for key in keys})

    if shell == "systemd":
        lines = [f"{key}={ops[key]}" for key in keys if ops[key] is not None]
        return ("\n".join(lines) + ("\n" if lines else ""))

    raise CLIError(f"unknown target shell '{shell}'")


def eval_envrc(rc_path: Path, base_env: dict[str, str], cfg: Config) -> tuple[dict[str, str], str]:
    script = render_stdlib()
    strict_call = "strict_env " if cfg.strict_env else ""
    wrapper = f"""
__direnv_internal_load_rc() {{
  watch_file "$1"
  # shellcheck disable=SC1090
  source "$1"
}}
__direnv_internal_load_dotenv() {{
  dotenv "$1"
}}
if [[ "$1" == "--dotenv" ]]; then
  shift
  __main__ {strict_call}__direnv_internal_load_dotenv "$1"
else
  __main__ {strict_call}__direnv_internal_load_rc "$1"
fi
"""
    args = [cfg.bash_path, "-c", script + "\n" + wrapper, "direnv"]
    if rc_path.suffix == ".env":
        args += ["--dotenv", rc_path.name]
    else:
        args.append(rc_path.name)
    proc = subprocess.run(
        args,
        cwd=str(rc_path.parent),
        env=base_env,
        stdin=subprocess.DEVNULL if cfg.disable_stdin else None,
        capture_output=True,
        text=True,
    )
    if proc.stderr:
        sys.stderr.write(proc.stderr)
    stdout = proc.stdout.strip()
    if not stdout:
        return {}, ""
    try:
        dumped = json.loads(stdout)
    except json.JSONDecodeError:
        return {}, stdout
    env_out = {str(key): str(value) for key, value in dumped.items() if isinstance(value, str)}
    return env_out, stdout


def build_user_target(base_env: dict[str, str], dumped_env: dict[str, str]) -> dict[str, str]:
    target = dict(base_env)
    for key in list(target):
        if key in EVAL_IGNORED_VARS:
            continue
        if key not in dumped_env:
            target.pop(key, None)
    for key, value in dumped_env.items():
        if key in EVAL_IGNORED_VARS:
            continue
        target[key] = value
    for key in MANAGED_VARS:
        target.pop(key, None)
    return target


def build_export_plan(cfg: Config) -> tuple[Path | None, dict[str, str], dict[str, str | None], dict[str, str], dict[str, str | None], int, bool]:
    current_env = dict(os.environ)
    reverse_diff = reverse_diff_from_env()
    base_env = apply_reverse_diff(current_env, reverse_diff)
    found_rc = discover_rc(Path.cwd(), cfg)
    loaded_rc = os.environ.get("DIRENV_FILE")
    loaded_same = bool(found_rc and loaded_rc and Path(loaded_rc).resolve(strict=False) == found_rc)
    current_watches = decode_watches(os.environ.get("DIRENV_WATCHES"))
    needs_reload = not loaded_same or not watches_current(current_watches) or bool(os.environ.get("DIRENV_REQUIRED"))

    if found_rc and loaded_same and not needs_reload:
        return found_rc, current_env, {}, base_env, {}, 0, False

    user_reverse_ops = reverse_ops_from_diff(reverse_diff)
    metadata_ops: dict[str, str | None] = {}
    user_forward_ops: dict[str, str | None] = {}
    exit_code = 0

    if found_rc is None:
        for key in MANAGED_VARS:
            if key in current_env:
                metadata_ops[key] = None
        return None, current_env, {**user_reverse_ops, **metadata_ops}, base_env, {}, 0, True

    state, allow_path, deny_path = rc_auth_state(found_rc, cfg)
    watches = merge_watches(
        [],
        make_watch_entry(found_rc),
        make_watch_entry(allow_path),
        make_watch_entry(deny_path),
    )
    user_target = dict(base_env)
    metadata: dict[str, str] = {}

    if state == 1:
        metadata = {
            "DIRENV_DIR": f"-{Path.cwd().resolve()}",
            "DIRENV_FILE": str(found_rc),
            "DIRENV_WATCHES": encode_watches(watches),
            "DIRENV_DIFF": encode_payload({}),
        }
        exit_code = 1
    elif state == 2:
        metadata = {
            "DIRENV_DIR": f"-{Path.cwd().resolve()}",
            "DIRENV_FILE": str(found_rc),
            "DIRENV_WATCHES": encode_watches(watches),
            "DIRENV_DIFF": encode_payload({}),
        }
    else:
        if found_rc.suffix == ".envrc":
            status_log(f"loading {found_rc}")
        dumped_env, _ = eval_envrc(found_rc, base_env, cfg)
        user_target = build_user_target(base_env, dumped_env)
        dumped_watches = decode_watches(dumped_env.get("DIRENV_WATCHES"))
        watches = merge_watches(
            dumped_watches,
            make_watch_entry(found_rc),
            make_watch_entry(allow_path),
            make_watch_entry(deny_path),
        )
        reverse_payload = build_reverse_diff(base_env, user_target)
        metadata = {
            "DIRENV_DIR": f"-{Path.cwd().resolve()}",
            "DIRENV_FILE": str(found_rc),
            "DIRENV_WATCHES": encode_watches(watches),
            "DIRENV_DIFF": encode_payload(reverse_payload),
        }
        if "DIRENV_REQUIRED" in dumped_env:
            metadata["DIRENV_REQUIRED"] = dumped_env["DIRENV_REQUIRED"]
        user_forward_ops = env_delta(base_env, user_target, ignored=MANAGED_VARS | VOLATILE_VARS)

    user_ops = dict(user_reverse_ops)
    user_ops.update(user_forward_ops)

    for key, value in metadata.items():
        metadata_ops[key] = value
    for key in MANAGED_VARS - metadata.keys():
        if key in current_env:
            metadata_ops[key] = None

    ops = dict(user_ops)
    ops.update(metadata_ops)
    final_target = dict(user_target)
    final_target.update(metadata)
    return found_rc, final_target, ops, base_env, user_ops, exit_code, True


def summarize_ops(ops: dict[str, str | None]) -> str:
    added = []
    removed = []
    changed = []
    current_env = dict(os.environ)
    for key in sorted(ops):
        if key in MANAGED_VARS:
            continue
        value = ops[key]
        before = current_env.get(key)
        if value is None:
            removed.append(f"-{key}")
        elif before is None:
            added.append(f"+{key}")
        else:
            changed.append(f"~{key}")
    return " ".join(added + removed + changed)


