        "elvish": f"""## hook for direnv
set @edit:before-readline = $@edit:before-readline {{
\ttry {{
\t\tvar m = [("{exe}" export elvish | from-json)]
\t\tif (> (count $m) 0) {{
\t\t\tset m = (all $m)
