def command_export(cfg: Config, shell: str) -> int:
    if shell not in PUBLIC_EXPORT_SHELLS:
        raise CLIError(f"unknown target shell '{shell}'")
    found_rc, _target_env, ops, _base_env, user_ops, exit_code, did_work = build_export_plan(cfg)

    if not did_work:
        return 0

    current_loaded = bool(os.environ.get("DIRENV_FILE"))
    if found_rc is None:
        if current_loaded:
            status_log("unloading")
    else:
        state, _, _ = rc_auth_state(found_rc, cfg)
        if state == 1:
            error_log(f"{found_rc} is blocked. Run `direnv allow` to approve its content")
        elif not cfg.hide_env_diff:
            summary = summarize_ops(user_ops)
            if summary:
                status_log(f"export {summary}")

    rendered = format_export_ops(shell, ops)
    if rendered:
        sys.stdout.write(rendered)
    return exit_code


def command_allow(cfg: Config, arg: str | None) -> int:
    rc_path = resolve_for_allow_or_block(arg, cfg)
    if not rc_path.exists():
        raise CLIError(".envrc file not found")
    allow_rc(rc_path)
    allow_required_files()
    return 0


def command_block(cfg: Config, arg: str | None) -> int:
    rc_path = resolve_for_allow_or_block(arg, cfg)
    if not rc_path.exists():
        raise CLIError(".envrc file not found")
    deny_rc(rc_path)
    return 0


def command_edit(cfg: Config, arg: str | None) -> int:
    target = resolve_for_edit(arg, cfg)
    editor = os.environ.get("EDITOR") or os.environ.get("VISUAL")
    if not editor:
        raise CLIError("no EDITOR configured")
    before = target.stat().st_mtime_ns if target.exists() else None
    ensure_parent(target)
    cmd = shlex.split(editor) + [str(target)]
    proc = subprocess.run(cmd)
    if proc.returncode != 0:
        return proc.returncode
    after = target.stat().st_mtime_ns if target.exists() else None
    if before != after and target.exists():
        allow_rc(target)
    return 0


def command_reload(cfg: Config) -> int:
    target = resolve_for_reload(cfg)
    if not target.exists():
        raise CLIError(".envrc not found")
    now = time.time()
    os.utime(target, (now, now))
    return 0


def build_exec_environment(cfg: Config, directory: Path) -> tuple[dict[str, str], int, Path | None]:
    current_env = dict(os.environ)
    reverse_diff = reverse_diff_from_env()
    base_env = apply_reverse_diff(current_env, reverse_diff)
    found_rc = discover_rc(directory.resolve(), cfg)
    if found_rc is None:
        return current_env, 0, None

    state, allow_path, deny_path = rc_auth_state(found_rc, cfg)
    if state == 1:
        raise CLIError(f"{found_rc} is blocked. Run `direnv allow` to approve its content")
    if state == 2:
        return base_env, 0, found_rc

    if found_rc.suffix == ".envrc":
        status_log(f"loading {found_rc}")
    dumped_env, _ = eval_envrc(found_rc, base_env, cfg)
    user_target = build_user_target(base_env, dumped_env)
    watches = merge_watches(
        decode_watches(dumped_env.get("DIRENV_WATCHES")),
        make_watch_entry(found_rc),
        make_watch_entry(allow_path),
        make_watch_entry(deny_path),
    )
    reverse_payload = build_reverse_diff(base_env, user_target)
    target_env = dict(user_target)
    target_env["DIRENV_DIR"] = f"-{directory.resolve()}"
    target_env["DIRENV_FILE"] = str(found_rc)
    target_env["DIRENV_WATCHES"] = encode_watches(watches)
    target_env["DIRENV_DIFF"] = encode_payload(reverse_payload)
    if "DIRENV_REQUIRED" in dumped_env:
        target_env["DIRENV_REQUIRED"] = dumped_env["DIRENV_REQUIRED"]
    if "DIRENV_IN_ENVRC" in dumped_env:
        target_env["DIRENV_IN_ENVRC"] = dumped_env["DIRENV_IN_ENVRC"]
    return target_env, 0, found_rc


def command_exec(cfg: Config, args: list[str]) -> int:
    if len(args) < 2:
        raise CLIError("invalid arguments")
    directory = path_for_arg(args[0])
    assert directory is not None
    env, _status, _found = build_exec_environment(cfg, directory)
    proc = subprocess.run(args[1:], env=env)
    return proc.returncode


def command_status(cfg: Config, json_mode: bool) -> int:
    found = discover_rc(Path.cwd(), cfg)
    loaded_raw = os.environ.get("DIRENV_FILE")
    loaded = Path(loaded_raw).resolve(strict=False) if loaded_raw else None
    found_state = None
    loaded_state = None

    if found is not None:
        state, allow_path, _ = rc_auth_state(found, cfg)
        found_state = {"allowed": state, "path": str(found), "allowPath": str(allow_path)}
    if loaded is not None:
        state, allow_path, _ = rc_auth_state(loaded, cfg)
        loaded_state = {"allowed": state, "path": str(loaded), "allowPath": str(allow_path)}

    if json_mode:
        payload = {
            "config": {
                "ConfigDir": str(config_dir()),
                "SelfPath": str(self_path()),
            },
            "state": {
                "foundRC": None if found_state is None else {"allowed": found_state["allowed"], "path": found_state["path"]},
                "loadedRC": None if loaded_state is None else {"allowed": loaded_state["allowed"], "path": loaded_state["path"]},
            },
        }
        sys.stdout.write(json.dumps(payload, indent=2) + "\n")
        return 0

    sys.stdout.write(f"direnv exec path {self_path()}\n")
    sys.stdout.write(f"DIRENV_CONFIG {config_dir()}\n")
    sys.stdout.write(f"bash_path {cfg.bash_path}\n")
    sys.stdout.write(f"disable_stdin {'true' if cfg.disable_stdin else 'false'}\n")
    sys.stdout.write(f"warn_timeout {cfg.warn_timeout}\n")
    prefix_repr = " ".join(cfg.whitelist_prefix)
    sys.stdout.write(f"whitelist.prefix [{prefix_repr}]\n")
    if cfg.whitelist_exact:
        exact_repr = " ".join(f"{item}:{{}}" for item in sorted(cfg.whitelist_exact))
        sys.stdout.write(f"whitelist.exact map[{exact_repr}]\n")
    else:
        sys.stdout.write("whitelist.exact map[]\n")

    if loaded_state is None:
        sys.stdout.write("No .envrc or .env loaded\n")
    else:
        sys.stdout.write(f"Loaded RC path {loaded_state['path']}\n")
        for watch in decode_watches(os.environ.get("DIRENV_WATCHES")):
            watch_path = Path(watch["path"])
            sys.stdout.write(f'Loaded watch: "{display_path(str(watch_path))}" - {mtime_for_display(watch_path)}\n')
        sys.stdout.write(f"Loaded RC allowed {loaded_state['allowed']}\n")
        sys.stdout.write(f"Loaded RC allowPath {loaded_state['allowPath']}\n")

    if found_state is None:
        sys.stdout.write("No .envrc or .env found\n")
    else:
        sys.stdout.write(f"Found RC path {found_state['path']}\n")
        _, allow_path, deny_path = rc_auth_state(found, cfg)
        for watch_path in [found, allow_path, deny_path]:
            sys.stdout.write(f'Found watch: "{display_path(str(watch_path))}" - {mtime_for_display(watch_path)}\n')
        sys.stdout.write(f"Found RC allowed {found_state['allowed']}\n")
        sys.stdout.write(f"Found RC allowPath {found_state['allowPath']}\n")
    return 0


