def command_version(args: list[str]) -> int:
    if not args:
        sys.stdout.write(VERSION + "\n")
        return 0
    wanted = args[0]
    if version_at_least(VERSION, wanted):
        return 0
    error_log(f"current version v{VERSION} is older than the desired version {wanted if wanted.startswith('v') else 'v' + wanted}")
    return 1


