def command_fetchurl(args: list[str]) -> int:
    if not args:
        raise CLIError("missing URL argument")
    url = args[0]
    integrity = args[1] if len(args) > 1 else None
    try:
        with urllib.request.urlopen(url) as response:
            data = response.read()
    except (urllib.error.URLError, ValueError) as exc:
        raise CLIError(str(exc))

    digest = hashlib.sha256(data).digest()
    sri = "sha256-" + base64.b64encode(digest).decode("ascii")

    if integrity is None:
        if sys.stdout.isatty():
            sys.stdout.write(f"Found hash: {sri}\n\n")
        else:
            sys.stdout.write(sri + "\n")
        return 0

    if integrity != sri:
        raise CLIError(f"integrity mismatch, expected {integrity}, got {sri}")

    cas_dir = cache_dir() / "direnv" / "cas"
    cas_dir.mkdir(parents=True, exist_ok=True)
    filename = integrity.replace("/", "_")
    path = cas_dir / filename
    if not path.exists():
        path.write_bytes(data)
        path.chmod(0o555)
    sys.stdout.write(str(path) + "\n")
    return 0


DOTENV_RE = re.compile(r"^(?:export[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$")


def parse_dotenv_value(raw: str) -> str:
    value = raw.strip()
    if value.startswith("'") and value.endswith("'") and len(value) >= 2:
        return value[1:-1]
    if value.startswith('"') and value.endswith('"') and len(value) >= 2:
        inner = value[1:-1]
        return bytes(inner, "utf-8").decode("unicode_escape")
    if " " in value or "\t" in value:
        raise CLIError(f"invalid line: {raw}")
    return value


def parse_dotenv_file(path: Path) -> dict[str, str]:
    parsed: dict[str, str] = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        match = DOTENV_RE.match(line)
        if not match:
            raise CLIError(f"invalid line: {line}")
        key, raw = match.groups()
        parsed[key] = parse_dotenv_value(raw)
    return parsed


def command_dotenv(args: list[str]) -> int:
    shell = "bash"
    path_arg = None
    if args:
        if args[0] in PUBLIC_EXPORT_SHELLS or args[0] in {"bash"}:
            shell = args[0]
            path_arg = args[1] if len(args) > 1 else None
        else:
            path_arg = args[0]
    path = path_for_arg(path_arg) if path_arg else (Path.cwd() / ".env")
    assert path is not None
    values = parse_dotenv_file(path)
    ops = {key: value for key, value in values.items()}
    rendered = format_export_ops(shell, ops)
    if rendered:
        sys.stdout.write(rendered)
    return 0


def command_dump(args: list[str]) -> int:
    shell = args[0] if args else "json"
    file_arg = args[1] if len(args) > 1 and args[1] else None
    payload = json.dumps(dict(os.environ), indent=2, sort_keys=True) + "\n"
    dump_path = os.environ.get("DIRENV_DUMP_FILE_PATH") or file_arg
    if dump_path:
        Path(dump_path).write_text(payload, encoding="utf-8")
        if os.environ.get("DIRENV_DUMP_FILE_PATH") and not file_arg:
            return 0
    if shell == "json":
        sys.stdout.write(payload)
        return 0
    sys.stdout.write(payload)
    return 0


def command_apply_dump(args: list[str]) -> int:
