    target = Path(args[0]).expanduser()
    dumped = json.loads(target.read_text(encoding="utf-8"))
    current_env = dict(os.environ)
    desired = {str(key): str(value) for key, value in dumped.items() if isinstance(value, str)}
    ops = env_delta(current_env, desired, ignored=VOLATILE_VARS)
    sys.stdout.write(format_export_ops("bash", ops))
