def command_watch(args: list[str], recursive: bool = False) -> int:
    if len(args) < 2:
        raise CLIError("invalid arguments")
    shell = args[0]
    entries = decode_watches(os.environ.get("DIRENV_WATCHES"))
    for raw in args[1:]:
        path = path_for_arg(raw)
        assert path is not None
        entries = merge_watches(entries, make_watch_entry(path, recursive=recursive))
    rendered = format_export_ops(shell, {"DIRENV_WATCHES": encode_watches(entries)})
    if rendered:
        sys.stdout.write(rendered)
    return 0


def command_watch_list(args: list[str]) -> int:
    shell = args[0] if args else "bash"
    entries = []
    for line in sys.stdin.read().splitlines():
        if not line.strip():
            continue
        try:
            _mtime, path = line.split(" ", 1)
        except ValueError:
            continue
        target = path_for_arg(path)
        if target is None:
            continue
        entries.append(make_watch_entry(target))
    rendered = format_export_ops(shell, {"DIRENV_WATCHES": encode_watches(entries)})
    if rendered:
        sys.stdout.write(rendered)
    return 0


def command_watch_print(args: list[str]) -> int:
    null_mode = bool(args and args[0] == "--null")
    sep = "\0" if null_mode else "\n"
    entries = decode_watches(os.environ.get("DIRENV_WATCHES"))
    data = sep.join(item["path"] for item in entries)
    if data:
        sys.stdout.write(data)
        if not null_mode:
            sys.stdout.write("\n")
    return 0


def command_current(args: list[str]) -> int:
    if len(args) != 1:
        raise CLIError("invalid arguments")
    target = path_for_arg(args[0])
    assert target is not None
    for item in decode_watches(os.environ.get("DIRENV_WATCHES")):
        if Path(item["path"]).resolve(strict=False) == target:
            current = dir_signature(target) if item.get("kind") == "dir" else file_signature(target)
            return 0 if current == item.get("signature") else 1
    return 1


def command_check_required(args: list[str]) -> int:
    if len(args) < 3:
        raise CLIError("invalid arguments")
    shell = args[0]
    envrc_path = Path(args[1]).expanduser().resolve(strict=False)
    missing = []
    bucket = required_bucket(envrc_path)
    for rel in args[2:]:
        target = (Path.cwd() / rel).resolve()
        approval = bucket / required_hash(target)
        if not approval.exists():
            missing.append(rel)
    if not missing:
        return 0
    joined = "\n".join(missing)
    if shell == "bash":
        sys.stdout.write(
            f"export DIRENV_REQUIRED={bash_quote(joined)};log_error {bash_quote(missing[0] + \" requires approval. Run 'direnv allow' to approve.\")};\n"
            "exit 0;\n"
        )
        return 0
    rendered = format_export_ops(shell, {"DIRENV_REQUIRED": joined})
    sys.stdout.write(rendered)
    return 0


def dispatch(argv: list[str]) -> int:
    cfg = load_config()

    if not argv or argv[0] in {"help", "--help"}:
        show_private = len(argv) > 1 and argv[1].lower() == "true"
        return command_help(show_private)

    command = argv[0]
    args = argv[1:]

    aliases = {
        "grant": "allow",
        "permit": "allow",
        "deny": "block",
        "disallow": "block",
        "revoke": "block",
    }
    command = aliases.get(command, command)

    if command == "allow":
        return command_allow(cfg, args[0] if args else None)
    if command == "block":
        return command_block(cfg, args[0] if args else None)
    if command == "edit":
        return command_edit(cfg, args[0] if args else None)
    if command == "exec":
        return command_exec(cfg, args)
    if command == "export":
        if len(args) != 1:
            raise CLIError("invalid arguments")
        return command_export(cfg, args[0])
    if command == "fetchurl":
        return command_fetchurl(args)
    if command == "hook":
        if len(args) != 1:
            raise CLIError("invalid arguments")
        return command_hook(args[0])
    if command == "prune":
        prune_entries()
        return 0
    if command == "reload":
        return command_reload(cfg)
    if command == "status":
        json_mode = len(args) == 1 and args[0] == "--json"
        if args and not json_mode:
            raise CLIError("invalid arguments")
        return command_status(cfg, json_mode)
    if command == "stdlib":
        return command_stdlib()
    if command == "version":
        return command_version(args)
    if command == "log":
        return command_log(args)

    if command == "dotenv":
        return command_dotenv(args)
    if command == "dump":
        return command_dump(args)
    if command == "apply_dump":
        return command_apply_dump(args)
    if command == "show_dump":
        return command_show_dump(args)
    if command == "watch":
        return command_watch(args, recursive=False)
    if command == "watch-dir":
        return command_watch(args, recursive=True)
    if command == "watch-list":
        return command_watch_list(args)
    if command == "watch-print":
        return command_watch_print(args)
    if command == "current":
        return command_current(args)
    if command == "check-required":
        return command_check_required(args)

    raise CLIError(f'command "{sys.argv[0]} {argv[0]}" not found')


def main() -> int:
    try:
        return dispatch(sys.argv[1:])
    except CLIError as exc:
        error_log(exc.message)
        return exc.exit_code


if __name__ == "__main__":
    raise SystemExit(main())

